## **1. Finding the Inverse of a 3×3 Matrix**
```c
#include <stdio.h>

#define SIZE 3

// Function to calculate determinant
int determinant(int matrix[SIZE][SIZE]) {
    return matrix[0][0] * (matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1]) -
           matrix[0][1] * (matrix[1][0] * matrix[2][2] - matrix[1][2] * matrix[2][0]) +
           matrix[0][2] * (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0]);
}

// Function to find the inverse of a matrix
void inverseMatrix(int matrix[SIZE][SIZE]) {
    int det = determinant(matrix);
    if (det == 0) {
        printf("Inverse does not exist (Determinant is zero).\n");
        return;
    }

    // Finding adjoint matrix
    int adj[SIZE][SIZE];
    adj[0][0] = matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1];
    adj[0][1] = -(matrix[1][0] * matrix[2][2] - matrix[1][2] * matrix[2][0]);
    adj[0][2] = matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0];
    adj[1][0] = -(matrix[0][1] * matrix[2][2] - matrix[0][2] * matrix[2][1]);
    adj[1][1] = matrix[0][0] * matrix[2][2] - matrix[0][2] * matrix[2][0];
    adj[1][2] = -(matrix[0][0] * matrix[2][1] - matrix[0][1] * matrix[2][0]);
    adj[2][0] = matrix[0][1] * matrix[1][2] - matrix[0][2] * matrix[1][1];
    adj[2][1] = -(matrix[0][0] * matrix[1][2] - matrix[0][2] * matrix[1][0]);
    adj[2][2] = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];

    printf("Inverse Matrix:\n");
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            printf("%.2f ", (float)adj[i][j] / det);
        }
        printf("\n");
    }
}

int main() {
    int matrix[SIZE][SIZE] = {
        {2, -1, 0},
        {1, 2, 1},
        {3, 0, 2}
    };

    inverseMatrix(matrix);

    return 0;
}
```
