### **C Program to Check If a Matrix is Symmetric (Without #define SIZE 3)**
```c
#include <stdio.h>

int isSymmetric(int matrix[][10], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (matrix[i][j] != matrix[j][i]) {
                return 0; // Not symmetric
            }
        }
    }
    return 1; // Symmetric
}

int main() {
    int n;
    printf("Enter the size of the square matrix: ");
    scanf("%d", &n);

    int matrix[10][10]; // Assuming max size is 10x10 for simplicity
    printf("Enter the elements of the %dx%d matrix:\n", n, n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    if (isSymmetric(matrix, n)) {
        printf("The matrix is Symmetric.\n");
    } else {
        printf("The matrix is NOT Symmetric.\n");
    }

    return 0;
}
```

---

### **How This Works**
1. **Takes `n` as user input** for the matrix size.
2. **Reads a `n×n` matrix** from the user.
3. **Checks if matrix[i][j] == matrix[j][i]** for all `i` and `j`.
4. **Prints whether the matrix is symmetric or not.**

