## **4. Checking If a Matrix is an Orthogonal Matrix**  
A matrix is **orthogonal** if **A × Aᵀ = Identity Matrix**.  
```c
#include <stdio.h>

void transpose(int matrix[][10], int trans[][10], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            trans[j][i] = matrix[i][j];
        }
    }
}

void multiplyMatrices(int A[][10], int B[][10], int result[][10], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            result[i][j] = 0;
            for (int k = 0; k < n; k++) {
                result[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

int isIdentityMatrix(int matrix[][10], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if ((i == j && matrix[i][j] != 1) || (i != j && matrix[i][j] != 0)) {
                return 0;
            }
        }
    }
    return 1;
}

int isOrthogonalMatrix(int matrix[][10], int n) {
    int trans[10][10], result[10][10];
    transpose(matrix, trans, n);
    multiplyMatrices(matrix, trans, result, n);
    return isIdentityMatrix(result, n);
}

int main() {
    int n;
    printf("Enter the size of the square matrix: ");
    scanf("%d", &n);

    int matrix[10][10];
    printf("Enter the elements of the %dx%d matrix:\n", n, n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    if (isOrthogonalMatrix(matrix, n)) {
        printf("The matrix is an Orthogonal Matrix.\n");
    } else {
        printf("The matrix is NOT an Orthogonal Matrix.\n");
    }

    return 0;
}
```

