    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    int trace = calculateTrace(matrix, n);
    printf("Trace of the matrix: %d\n", trace);

    return 0;
}
